#include "vmx_ept_hook_owner.h"
#include <stddef.h>
#include <string.h>
static int Zero(const void*v,size_t n){const unsigned char*p=(const unsigned char*)v;size_t i;if(!v)return 0;for(i=0;i<n;++i)if(p[i])return 0;return 1;}
static int AllocatorValid(const VMX_PERSISTENT_ALLOCATOR*a){return a&&a->AllocatePool&&a->FreePool&&a->AllocateContiguous&&a->FreeContiguous&&a->GetPhysicalAddress;}
static int AllocatorEqual(const VMX_PERSISTENT_ALLOCATOR*a,const VMX_PERSISTENT_ALLOCATOR*b){return a->Context==b->Context&&a->AllocatePool==b->AllocatePool&&a->FreePool==b->FreePool&&a->AllocateContiguous==b->AllocateContiguous&&a->FreeContiguous==b->FreeContiguous&&a->GetPhysicalAddress==b->GetPhysicalAddress;}
static int Span(const void*v,size_t n,uintptr_t*b,uintptr_t*e){uintptr_t f=(uintptr_t)v;if(!v||!n||f>UINTPTR_MAX-n)return 0;*b=f;*e=f+n;return 1;}
static int Separate(const void*l,size_t ln,const void*r,size_t rn){uintptr_t lb,le,rb,re;return Span(l,ln,&lb,&le)&&Span(r,rn,&rb,&re)&&(le<=rb||re<=lb);}
static int InitializeSeparate(const VMX_EPT_SESSION_OWNER*s,const VMX_PERSISTENT_ALLOCATOR*a,const VMX_EPT_HOOK_OWNER*o){return s&&a&&o&&Separate(s,sizeof(*s),o,sizeof(*o))&&Separate(a,sizeof(*a),o,sizeof(*o))&&(a==&s->Allocator||Separate(s,sizeof(*s),a,sizeof(*a)));}
static int SessionSeparate(const VMX_EPT_SESSION_OWNER*s,const void*v,size_t n){const VMX_EPT_STORAGE_OWNER*t;size_t pages,index;if(!s||!v||s->GraphBytes>SIZE_MAX||VmxEptSessionOwnerValidate(s)!=VMX_EPT_SESSION_OK)return 0;t=s->Storage;if(t->TableBytes>SIZE_MAX||t->PageCount>SIZE_MAX/sizeof(*t->PagesByOrdinal)||t->PageCount>SIZE_MAX/sizeof(*t->PhysicalIndex))return 0;pages=(size_t)t->PageCount*sizeof(*t->PagesByOrdinal);index=(size_t)t->PageCount*sizeof(*t->PhysicalIndex);return Separate(s,sizeof(*s),v,n)&&Separate(s->Graph,(size_t)s->GraphBytes,v,n)&&Separate(t->Tables,(size_t)t->TableBytes,v,n)&&Separate(t->PagesByOrdinal,pages,v,n)&&Separate(t->PhysicalIndex,index,v,n);}
static int OwnerSeparate(const VMX_EPT_HOOK_OWNER*o,const void*v,size_t n){size_t slots;if(!o||!v||o->Capacity>SIZE_MAX/sizeof(*o->Slots))return 0;slots=(size_t)o->Capacity*sizeof(*o->Slots);return Separate(o,sizeof(*o),v,n)&&Separate(o->Slots,slots,v,n)&&SessionSeparate(o->Session,v,n);}
static uint64_t* ParentEntry(VMX_EPT_HOOK_OWNER*o,const VMX_EPT_HOOK_SLOT*s){return (uint64_t*)((unsigned char*)o->Session->Storage->Tables+(size_t)s->Location.ParentPageOrdinal*VMX_EPT_TABLE_PAGE_SIZE)+(size_t)s->Location.ParentEntryIndex;}
static int SlotValid(const VMX_EPT_HOOK_OWNER*o,const VMX_EPT_HOOK_SLOT*s){if(s->Record.Stage==VMX_EPT_HOOK_STAGE_FREE)return Zero(s,sizeof(*s));return VmxEptHookRecordValid(&s->Record)&&s->PageTable&&!(s->PageTablePhysicalAddress&4095)&&s->PageTablePhysicalAddress==s->Record.Plan.PageTablePhysicalAddress&&s->Location.GuestPhysicalPage==s->Record.Plan.GuestPhysicalPage&&s->Location.ObservedParentEntry==s->Record.Plan.OriginalParentEntry&&s->Location.ParentPageOrdinal<o->Session->Storage->PageCount&&s->Location.ParentEntryIndex<512&&s->Reserved[0]==0&&s->Reserved[1]==0;}
static int OwnerValid(const VMX_EPT_HOOK_OWNER*o){uint32_t i,j,active=0;size_t slot_bytes;if(!o||o->Magic!=VMX_EPT_HOOK_OWNER_MAGIC||o->Version!=VMX_EPT_HOOK_OWNER_VERSION||o->Stage!=VMX_EPT_HOOK_OWNER_READY||!o->Capacity||o->Capacity>SIZE_MAX/sizeof(*o->Slots)||o->ActiveCount>o->Capacity||o->Reserved32||!AllocatorValid(&o->Allocator)||!AllocatorEqual(&o->Allocator,&o->AllocatorContract)||!o->Session||o->Session!=o->SessionContract||VmxEptSessionOwnerValidate(o->Session)!=VMX_EPT_SESSION_OK||!o->Slots||o->Reserved[0]||o->Reserved[1])return 0;slot_bytes=(size_t)o->Capacity*sizeof(*o->Slots);if(!Separate(o,sizeof(*o),o->Slots,slot_bytes)||!SessionSeparate(o->Session,o->Slots,slot_bytes))return 0;for(i=0;i<o->Capacity;++i){if(!SlotValid(o,&o->Slots[i]))return 0;if(o->Slots[i].Record.Stage!=VMX_EPT_HOOK_STAGE_FREE){if(!OwnerSeparate(o,o->Slots[i].PageTable,VMX_EPT_TABLE_PAGE_SIZE))return 0;for(j=0;j<i;++j)if(o->Slots[j].Record.Stage!=VMX_EPT_HOOK_STAGE_FREE&&!Separate(o->Slots[j].PageTable,VMX_EPT_TABLE_PAGE_SIZE,o->Slots[i].PageTable,VMX_EPT_TABLE_PAGE_SIZE))return 0;active++;}}return active==o->ActiveCount;}
static VMX_EPT_HOOK_OWNER_STATUS MapOperation(VMX_EPT_SESSION_OPERATION_STATUS s){if(s==VMX_EPT_SESSION_OPERATION_BUSY)return VMX_EPT_HOOK_OWNER_BUSY;if(s==VMX_EPT_SESSION_OPERATION_DIRTY)return VMX_EPT_HOOK_OWNER_DIRTY;if(s==VMX_EPT_SESSION_OPERATION_UNSUPPORTED)return VMX_EPT_HOOK_OWNER_UNSUPPORTED;return VMX_EPT_HOOK_OWNER_INVARIANT;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerValidate(const VMX_EPT_HOOK_OWNER*o){return OwnerValid(o)?VMX_EPT_HOOK_OWNER_OK:VMX_EPT_HOOK_OWNER_INVALID;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerValidateExternalSpan(const VMX_EPT_HOOK_OWNER*o,const void*v,size_t n){return OwnerValid(o)&&OwnerSeparate(o,v,n)?VMX_EPT_HOOK_OWNER_OK:VMX_EPT_HOOK_OWNER_INVALID;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerQuery(const VMX_EPT_HOOK_OWNER*o,uint64_t gpa,uint32_t*out_id,uint32_t*out_stage){uint32_t i;if(!OwnerValid(o)||!out_id||!out_stage||!OwnerSeparate(o,out_id,sizeof(*out_id))||!OwnerSeparate(o,out_stage,sizeof(*out_stage))||!Separate(out_id,sizeof(*out_id),out_stage,sizeof(*out_stage)))return VMX_EPT_HOOK_OWNER_INVALID;for(i=0;i<o->Capacity;++i)if(o->Slots[i].Record.Stage!=VMX_EPT_HOOK_STAGE_FREE&&o->Slots[i].Record.Plan.GuestPhysicalPage==gpa){*out_id=i;*out_stage=o->Slots[i].Record.Stage;return VMX_EPT_HOOK_OWNER_OK;}return VMX_EPT_HOOK_OWNER_NOT_FOUND;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerQueryFirst(const VMX_EPT_HOOK_OWNER*o,uint64_t*out_gpa,uint32_t*out_id,uint32_t*out_stage){uint32_t i;if(!OwnerValid(o)||!out_gpa||!out_id||!out_stage||!OwnerSeparate(o,out_gpa,sizeof(*out_gpa))||!OwnerSeparate(o,out_id,sizeof(*out_id))||!OwnerSeparate(o,out_stage,sizeof(*out_stage))||!Separate(out_gpa,sizeof(*out_gpa),out_id,sizeof(*out_id))||!Separate(out_gpa,sizeof(*out_gpa),out_stage,sizeof(*out_stage))||!Separate(out_id,sizeof(*out_id),out_stage,sizeof(*out_stage)))return VMX_EPT_HOOK_OWNER_INVALID;for(i=0;i<o->Capacity;++i)if(o->Slots[i].Record.Stage!=VMX_EPT_HOOK_STAGE_FREE){*out_gpa=o->Slots[i].Record.Plan.GuestPhysicalPage;*out_id=i;*out_stage=o->Slots[i].Record.Stage;return VMX_EPT_HOOK_OWNER_OK;}return VMX_EPT_HOOK_OWNER_NOT_FOUND;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerInitialize(VMX_EPT_SESSION_OWNER*s,uint32_t capacity,const VMX_PERSISTENT_ALLOCATOR*a,VMX_EPT_HOOK_OWNER*o){VMX_PERSISTENT_ALLOCATOR allocator;VMX_EPT_HOOK_OWNER x;int canonical_allocator;size_t bytes;if(!capacity||capacity>SIZE_MAX/sizeof(VMX_EPT_HOOK_SLOT)||!InitializeSeparate(s,a,o))return VMX_EPT_HOOK_OWNER_INVALID;canonical_allocator=a==&s->Allocator;if(VmxEptSessionOwnerValidate(s)!=VMX_EPT_SESSION_OK)return VMX_EPT_HOOK_OWNER_INVALID;allocator=canonical_allocator?s->Allocator:*a;if(!AllocatorValid(&allocator))return VMX_EPT_HOOK_OWNER_INVALID;if((!canonical_allocator&&!SessionSeparate(s,a,sizeof(*a)))||!SessionSeparate(s,o,sizeof(*o))||!Zero(o,sizeof(*o))||s->Storage->Domain.Identity.LeafKind!=VMX_EPT_ENTRY_LEAF_2MB)return VMX_EPT_HOOK_OWNER_INVALID;bytes=(size_t)capacity*sizeof(VMX_EPT_HOOK_SLOT);memset(&x,0,sizeof(x));x.Allocator=allocator;x.AllocatorContract=allocator;x.Session=s;x.SessionContract=s;x.Capacity=capacity;x.Slots=allocator.AllocatePool(allocator.Context,bytes);if(!x.Slots)return VMX_EPT_HOOK_OWNER_ALLOCATION_FAILED;if(!Separate(o,sizeof(*o),x.Slots,bytes)||!SessionSeparate(s,x.Slots,bytes)){allocator.FreePool(allocator.Context,x.Slots);return VMX_EPT_HOOK_OWNER_INVARIANT;}memset(x.Slots,0,bytes);x.Magic=VMX_EPT_HOOK_OWNER_MAGIC;x.Version=VMX_EPT_HOOK_OWNER_VERSION;x.Stage=VMX_EPT_HOOK_OWNER_READY;if(!OwnerValid(&x)){allocator.FreePool(allocator.Context,x.Slots);return VMX_EPT_HOOK_OWNER_INVARIANT;}*o=x;return VMX_EPT_HOOK_OWNER_OK;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerPrepare(VMX_EPT_HOOK_OWNER*o,uint64_t gpa,uint8_t traps,uint32_t*out_id){VMX_EPT_HOOK_LOCATION l;VMX_EPT_HOOK_PLAN p;VMX_EPT_HOOK_SLOT staged;VMX_EPT_SESSION_OPERATION_STATUS ss;uint64_t highest,pa;void*pt;uint32_t i,free_id=UINT32_MAX;if(!OwnerValid(o)||!out_id||!OwnerSeparate(o,out_id,sizeof(*out_id)))return VMX_EPT_HOOK_OWNER_INVALID;for(i=0;i<o->Capacity;++i){if(o->Slots[i].Record.Stage==VMX_EPT_HOOK_STAGE_FREE&&free_id==UINT32_MAX)free_id=i;else if(o->Slots[i].Record.Plan.GuestPhysicalPage==gpa)return VMX_EPT_HOOK_OWNER_BUSY;}if(free_id==UINT32_MAX)return VMX_EPT_HOOK_OWNER_BUSY;if(VmxEptHookLocate2Mb(&o->Session->Storage->Domain,gpa,&l)!=VMX_EPT_HOOK_LOCATION_OK)return VMX_EPT_HOOK_OWNER_UNSUPPORTED;highest=(UINT64_C(1)<<o->Session->Storage->Domain.Identity.PhysicalAddressBits)-1;pt=o->Allocator.AllocateContiguous(o->Allocator.Context,VMX_EPT_TABLE_PAGE_SIZE,highest);if(!pt)return VMX_EPT_HOOK_OWNER_ALLOCATION_FAILED;if(((uintptr_t)pt&4095)!=0||!OwnerSeparate(o,pt,VMX_EPT_TABLE_PAGE_SIZE))goto allocation_invalid;pa=o->Allocator.GetPhysicalAddress(o->Allocator.Context,pt);if(!pa||(pa&4095)||(pa>>o->Session->Storage->Domain.Identity.PhysicalAddressBits)!=0)goto allocation_invalid;if(VmxEptHookPlan2Mb(gpa,traps,l.ObservedParentEntry,pa,(uint64_t*)pt,&p)!=VMX_EPT_HOOK_OK)goto allocation_invalid;memset(&staged,0,sizeof(staged));staged.Location=l;staged.PageTable=pt;staged.PageTablePhysicalAddress=pa;if(o->Session->Storage->Domain.MutationGeneration==UINT64_MAX||VmxEptHookPrepare(&p,o->Session->Storage->Domain.MutationGeneration+1,&staged.Record)!=VMX_EPT_HOOK_OK)goto allocation_invalid;ss=VmxEptSessionBeginMutation(o->Session);if(ss!=VMX_EPT_SESSION_OPERATION_OK){o->Allocator.FreeContiguous(o->Allocator.Context,pt);return MapOperation(ss);}if(o->Session->Storage->Domain.MutationGeneration!=staged.Record.Generation)return VMX_EPT_HOOK_OWNER_INVARIANT;o->Slots[free_id]=staged;*ParentEntry(o,&o->Slots[free_id])=p.ReplacementParentEntry;o->ActiveCount++;*out_id=free_id;return OwnerValid(o)?VMX_EPT_HOOK_OWNER_OK:VMX_EPT_HOOK_OWNER_INVARIANT;allocation_invalid:o->Allocator.FreeContiguous(o->Allocator.Context,pt);return VMX_EPT_HOOK_OWNER_INVARIANT;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerCommit(VMX_EPT_HOOK_OWNER*o,uint32_t id){VMX_EPT_HOOK_SLOT*s;uint64_t parent,target;if(!OwnerValid(o)||id>=o->Capacity)return VMX_EPT_HOOK_OWNER_INVALID;s=&o->Slots[id];if(s->Record.Stage!=VMX_EPT_HOOK_STAGE_PREPARED)return VMX_EPT_HOOK_OWNER_BUSY;if(o->Session->Storage->Domain.PendingGeneration||o->Session->Storage->Domain.InvalidatedGeneration!=s->Record.Generation)return VMX_EPT_HOOK_OWNER_DIRTY;parent=*ParentEntry(o,s);target=((uint64_t*)s->PageTable)[s->Record.Plan.TargetIndex];return VmxEptHookCommit(&s->Record,parent,target)==VMX_EPT_HOOK_OK?VMX_EPT_HOOK_OWNER_OK:VMX_EPT_HOOK_OWNER_INVARIANT;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerBeginUnhook(VMX_EPT_HOOK_OWNER*o,uint64_t gpa,uint32_t*out_id){VMX_EPT_HOOK_SLOT*s=0;VMX_EPT_HOOK_RECORD staged_record;VMX_EPT_SESSION_OPERATION_STATUS ss;uint32_t i;if(!OwnerValid(o)||!out_id||!OwnerSeparate(o,out_id,sizeof(*out_id)))return VMX_EPT_HOOK_OWNER_INVALID;for(i=0;i<o->Capacity;++i)if(o->Slots[i].Record.Stage!=VMX_EPT_HOOK_STAGE_FREE&&o->Slots[i].Record.Plan.GuestPhysicalPage==gpa){s=&o->Slots[i];break;}if(!s)return VMX_EPT_HOOK_OWNER_NOT_FOUND;if(s->Record.Stage!=VMX_EPT_HOOK_STAGE_COMMITTED)return VMX_EPT_HOOK_OWNER_BUSY;if(o->Session->Storage->Domain.MutationGeneration==UINT64_MAX)return VMX_EPT_HOOK_OWNER_DIRTY;staged_record=s->Record;if(VmxEptHookBeginRollback(&staged_record,o->Session->Storage->Domain.MutationGeneration+1)!=VMX_EPT_HOOK_OK)return VMX_EPT_HOOK_OWNER_INVARIANT;ss=VmxEptSessionBeginMutation(o->Session);if(ss!=VMX_EPT_SESSION_OPERATION_OK)return MapOperation(ss);if(o->Session->Storage->Domain.MutationGeneration!=staged_record.Generation)return VMX_EPT_HOOK_OWNER_INVARIANT;s->Record=staged_record;((uint64_t*)s->PageTable)[s->Record.Plan.TargetIndex]=s->Record.Plan.OriginalTargetEntry;*ParentEntry(o,s)=s->Record.Plan.OriginalParentEntry;*out_id=i;return VMX_EPT_HOOK_OWNER_OK;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerCompleteUnhook(VMX_EPT_HOOK_OWNER*o,uint32_t id){VMX_EPT_HOOK_SLOT*s;VMX_EPT_HOOK_SLOT zero={0};uint64_t parent,target;if(!OwnerValid(o)||id>=o->Capacity)return VMX_EPT_HOOK_OWNER_INVALID;s=&o->Slots[id];if(s->Record.Stage!=VMX_EPT_HOOK_STAGE_ROLLBACK_PENDING)return VMX_EPT_HOOK_OWNER_BUSY;if(o->Session->Storage->Domain.PendingGeneration||o->Session->Storage->Domain.InvalidatedGeneration!=s->Record.Generation)return VMX_EPT_HOOK_OWNER_DIRTY;parent=*ParentEntry(o,s);target=((uint64_t*)s->PageTable)[s->Record.Plan.TargetIndex];if(VmxEptHookCompleteRollback(&s->Record,parent,target)!=VMX_EPT_HOOK_OK)return VMX_EPT_HOOK_OWNER_INVARIANT;o->Allocator.FreeContiguous(o->Allocator.Context,s->PageTable);*s=zero;o->ActiveCount--;return OwnerValid(o)?VMX_EPT_HOOK_OWNER_OK:VMX_EPT_HOOK_OWNER_INVARIANT;}
VMX_EPT_HOOK_OWNER_STATUS VmxEptHookOwnerDestroy(VMX_EPT_HOOK_OWNER*o){VMX_PERSISTENT_ALLOCATOR a;VMX_EPT_HOOK_SLOT*slots;if(!o)return VMX_EPT_HOOK_OWNER_INVALID;if(Zero(o,sizeof(*o)))return VMX_EPT_HOOK_OWNER_OK;if(!OwnerValid(o))return VMX_EPT_HOOK_OWNER_INVALID;if(o->ActiveCount)return VMX_EPT_HOOK_OWNER_BUSY;a=o->Allocator;slots=o->Slots;a.FreePool(a.Context,slots);memset(o,0,sizeof(*o));return VMX_EPT_HOOK_OWNER_OK;}
